cd /app && cat > seq.py <<'EOF'
import json, re
raw=json.load(open('ocrb.json'))
def clean(s):
    s=s.strip()
    # normalize the prompt char: OCR may give >, ), », etc as first char
    return s
# extract input after prompt marker
def inp(s):
    s=s.strip()
    if not s: return None  # blank -> no prompt visible (shouldn't happen)
    # find first '>' like char
    m=re.match(r'^[\s]*[>)»}]+\s?(.*)$', s)
    if m:
        return m.group(1).strip()
    # sometimes no prompt char captured; if line looks like C:\ end
    if s.startswith('C:') or 'C:\\' in s:
        return '__END__'
    return None
series=[inp(x) for x in raw]
# state machine
cmds=[]
pending=''
for cur in series:
    if cur is None:
        continue
    if cur=='__END__':
        if pending: cmds.append(pending); pending=''
        break
    if cur=='':
        # empty prompt -> finalize
        if pending: cmds.append(pending); pending=''
        continue
    # non-empty
    if pending=='' :
        pending=cur
    elif cur.startswith(pending) or pending.startswith(cur):
        # same command growing (or ocr flicker) -> keep longer
        pending=cur if len(cur)>=len(pending) else pending
    else:
        # diverged -> new command
        cmds.append(pending); pending=cur
if pending: cmds.append(pending)
print(len(cmds))
open('cmds_b.txt','w').write('\n'.join(cmds))
for i,c in enumerate(cmds): print(i,repr(c))
EOF
python3 seq.py 2>&1 | head -80
